<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/order_quote.php';require_once __DIR__.'/../lib/booking_reminders.php';
function assert_mail($condition,$message){if(!$condition)throw new RuntimeException($message);}
$q=mmb_order_quote(['package'=>'event','photo'=>'print700','microphone'=>2,'batteries'=>3,'backpack'=>1,'walls'=>1,'controller'=>1],'2030-01-11','2030-01-18','delivery_setup');
$b=['id'=>900,'customer_name'=>'Beispiel <script>alert(1)</script>','customer_email'=>'kunde@example.invalid','customer_phone'=>'+49 174 0000000','company_name'=>'Beispielfirma GmbH','billing_address_line1'=>'Rechnungsweg 1','billing_postal_code'=>'46485','billing_city'=>'Wesel','start_date'=>'2030-01-11','end_date'=>'2030-01-18','total_amount'=>$q['total'],'order'=>$q,'fulfillment_method'=>'delivery_setup','fulfillment_details'=>['company_name'=>'Eventfirma GmbH','contact_name'=>'Eventkontakt','address_line1'=>'Eventweg 2','postal_code'=>'46485','city'=>'Wesel','preferred_time'=>'14:30','meeting_point'=>'Seiteneingang'],'note'=>'Bitte kurz vorher melden.','verification_url'=>'https://firebrick-squirrel-568721.hostingersite.com/verify_booking_email.php?id=900&token='.str_repeat('a',64)];
foreach(['submission','internal','confirmed','updated','rejected','cancelled','alternative','reminder7','reminder3'] as $mode){$m=mmb_booking_message($b,$mode,['alternatives'=>['Marshall Bromley 750']]);foreach($q['items'] as $i)assert_mail(str_contains($m['text'],$i['label']),'Missing item '.$mode);foreach(['Beispielfirma','Eventfirma','14:30','Seiteneingang','Bitte kurz vorher melden.',mmb_mail_euro($q['total'])] as $v)assert_mail(str_contains($m['text'],$v),'Missing detail '.$v);assert_mail(!str_contains($m['html'],'<script>alert'),'HTML injection');assert_mail(str_contains($m['html'],'max-width:620px'),'Responsive shell missing');}
$ship=$b;$ship['fulfillment_method']='shipping';$m=mmb_booking_message($ship);assert_mail(!str_contains($m['text'],'14:30')&&!str_contains($m['text'],'Seiteneingang'),'Stale shipping timing');assert_mail(str_contains($m['text'],'Versandadresse'),'Shipping label');
$pickup=$b;$pickup['fulfillment_method']='pickup';$m=mmb_booking_message($pickup);assert_mail(!str_contains($m['text'],'Eventweg 2'),'Pickup destination leak');
$custom=mmb_booking_message($b,'updated',['custom_message'=>'Persönliche Nachricht','custom_subject'=>'Eigener Betreff']);assert_mail($custom['subject']==='Eigener Betreff'&&str_contains($custom['text'],'Aktueller gespeicherter Buchungsstand'),'Custom mail lost');
$legacy=$b;unset($legacy['order']);$legacy['box_id']=3;assert_mail(str_contains(mmb_booking_message($legacy)['text'],'SOUNDBOKS 4'),'Legacy equipment missing');
$r=['id'=>1,'status'=>'confirmed','email_verified_at'=>'2029-01-01','customer_name'=>'Kunde','customer_email'=>'test@example.invalid','start_date'=>'2030-01-11','fulfillment_method'=>'pickup'];
assert_mail(mmb_reminder_kind($r,new DateTimeImmutable('2030-01-04T12:00:00+01:00'))==='reminder7','7-day schedule');assert_mail(mmb_reminder_kind($r,new DateTimeImmutable('2030-01-08T12:00:00+01:00'))==='reminder3','3-day schedule');assert_mail(mmb_reminder_kind($r,new DateTimeImmutable('2030-01-09'))===null,'No stale catchup');
foreach(['pending','cancelled','rejected'] as $status){$n=$r;$n['status']=$status;assert_mail(mmb_reminder_kind($n,new DateTimeImmutable('2030-01-04'))===null,'Unsafe status');}
$n=$r;$n['customer_name']='TEST Beispiel';assert_mail(mmb_reminder_kind($n,new DateTimeImmutable('2030-01-04'))===null,'Test reminder');$n=$r;$n['email_verified_at']=null;assert_mail(mmb_reminder_kind($n,new DateTimeImmutable('2030-01-04'))===null,'Unverified reminder');
$missing=false;try{mmb_reminder_service($r,[]);}catch(RuntimeException $e){$missing=true;}assert_mail($missing,'Missing info accepted');
file_put_contents(__DIR__.'/communication-preview.html',mmb_booking_message($b,'submission')['html']);
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec('CREATE TABLE booking_mail_jobs (booking_id INTEGER,event_key TEXT,rental_start TEXT,recipient TEXT,status TEXT,created_at TEXT, UNIQUE(booking_id,event_key,rental_start))');assert_mail(mmb_reminder_claim($db,$r,'reminder7'),'Initial claim');assert_mail(!mmb_reminder_claim($db,$r,'reminder7'),'Duplicate claim');assert_mail(mmb_reminder_claim($db,$r,'reminder3'),'Independent reminder');
file_put_contents(__DIR__.'/communication-preview.html',mmb_booking_message($b,'submission')['html']);
echo "PASS: 9 complete responsive templates, XSS escaping, old bookings, addresses, custom text, reminder scheduling and duplicate suppression\n";
